// Height changes (including mobile browser chrome) must preserve a user's
// disclosure choice. Apply the default only on first load or a width breakpoint change.
let wideViewport;
const sync = () => {
  const viewportWidth = window.visualViewport?.width || document.documentElement?.clientWidth || window.innerWidth;
  const nextOpen = viewportWidth > 640;
  if (wideViewport === nextOpen) return;
  wideViewport = nextOpen;
  setOpen(nextOpen);
  if (detailsRef.current) detailsRef.current.open = nextOpen;
};
sync();
window.addEventListener("resize", sync);
window.visualViewport?.addEventListener("resize", sync);
return () => {
  window.removeEventListener("resize", sync);
  window.visualViewport?.removeEventListener("resize", sync);
};

